"""Unauthenticated REST API for the event database."""

import os
from typing import Any

from dotenv import load_dotenv
from flask import Flask, jsonify, request
from postgrest import APIError
from supabase import Client, create_client

load_dotenv()

app = Flask(__name__)

SUPABASE_URL = os.getenv("SUPABASE_URL")
SUPABASE_KEY = os.getenv("SUPABASE_PUBLISHABLE_KEY")
supabase: Client | None = (
    create_client(SUPABASE_URL, SUPABASE_KEY) if SUPABASE_URL and SUPABASE_KEY else None
)

# Writable columns shown in database.png. IDs and created_at are generated by the database.
TABLE_FIELDS = {
    "users": {"email", "role"},
    "events": {"organizer_id", "title", "capacity", "status"},
    "registrations": {"user_id", "event_id"},
}


@app.errorhandler(APIError)
def handle_database_error(error: APIError):
    return jsonify({"error": "Database request failed", "details": error.message}), 400


@app.errorhandler(400)
def handle_bad_request(error):
    description = getattr(error, "description", "Invalid request")
    return jsonify({"error": description}), 400


@app.errorhandler(404)
def handle_not_found(error):
    description = getattr(error, "description", "Not found")
    return jsonify({"error": description}), 404


def database() -> Client:
    if supabase is None:
        raise RuntimeError("Set SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY in .env")
    return supabase


def json_object() -> dict[str, Any]:
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        raise ValueError("Request body must be a JSON object")
    return data


def clean_fields(table: str, data: dict[str, Any], *, partial: bool = False):
    allowed = TABLE_FIELDS[table]
    unknown = set(data) - allowed
    if unknown:
        raise ValueError(f"Unsupported field(s): {', '.join(sorted(unknown))}")
    if not partial and not data:
        raise ValueError("Request body must include at least one field")
    return data


@app.errorhandler(ValueError)
def handle_validation_error(error: ValueError):
    return jsonify({"error": str(error)}), 400


@app.get("/")
def index():
    return jsonify({
        "name": "Event management API",
        "authentication": "disabled",
        "resources": ["users", "events", "registrations"],
        "utility_endpoints": ["/api/cube", "/api/is-positive"],
    })


def register_resource_routes(table: str):
    """Register list/create and read/update/delete routes for a table."""
    collection = f"/api/{table}"
    item = f"{collection}/<string:record_id>"

    def list_records():
        result = database().table(table).select("*").execute()
        return jsonify(result.data)

    def create_record():
        payload = clean_fields(table, json_object())
        result = database().table(table).insert(payload).select("*").execute()
        return jsonify(result.data[0] if result.data else {}), 201

    def get_record(record_id: str):
        result = database().table(table).select("*").eq("id", record_id).limit(1).execute()
        if not result.data:
            return jsonify({"error": f"{table[:-1] if table.endswith('s') else table} not found"}), 404
        return jsonify(result.data[0])

    def update_record(record_id: str):
        payload = clean_fields(table, json_object(), partial=True)
        if not payload:
            raise ValueError("Request body must include at least one field")
        result = database().table(table).update(payload).eq("id", record_id).select("*").execute()
        if not result.data:
            return jsonify({"error": "Record not found"}), 404
        return jsonify(result.data[0])

    def delete_record(record_id: str):
        result = database().table(table).delete().eq("id", record_id).select("*").execute()
        if not result.data:
            return jsonify({"error": "Record not found"}), 404
        return jsonify({"deleted": True, "id": record_id})

    endpoints = [
        (f"list_{table}", collection, ["GET"], list_records),
        (f"create_{table}", collection, ["POST"], create_record),
        (f"get_{table}", item, ["GET"], get_record),
        (f"update_{table}", item, ["PUT", "PATCH"], update_record),
        (f"delete_{table}", item, ["DELETE"], delete_record),
    ]
    for endpoint, rule, methods, view in endpoints:
        app.add_url_rule(rule, endpoint, view, methods=methods)


for resource_table in TABLE_FIELDS:
    register_resource_routes(resource_table)


@app.post("/api/cube")
def cube():
    number = json_object().get("number")
    if isinstance(number, bool) or not isinstance(number, (int, float)):
        raise ValueError("number must be numeric")
    return jsonify({"number": number, "cube": number**3})


@app.post("/api/is-positive")
def is_positive():
    number = json_object().get("number")
    if isinstance(number, bool) or not isinstance(number, (int, float)):
        raise ValueError("number must be numeric")
    return jsonify({"number": number, "is_positive": number > 0})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.getenv("PORT", "5000")), debug=os.getenv("FLASK_DEBUG") == "1")
